insert into public.topic_content
(topic_id,why_it_matters,core_idea,sub_variants,pattern_triggers,coverage_problems,red_flags)
values
(49,
'Randomness is an algorithmic resource, not a library call. Interview problems ask for exact uniformity, memory-bounded sampling from streams or huge implicit domains, unbiased conversion between random sources, and data structures that preserve O(1) operations while supporting random access. The hard part is proving the distribution, including after updates and deletions.',
'Start by stating the sample space and proving every desired outcome has the same probability. Fisher–Yates creates a uniform permutation by choosing the next position uniformly from the unshuffled suffix. Reservoir sampling maintains a uniform sample from a stream without knowing its final length. Rejection sampling removes bias by discarding excess outcomes rather than applying modulo to a non-divisible range. Inverse transforms map independent uniform variables to continuous distributions. Weighted sampling maps a uniform integer to a prefix-sum interval. Sparse Fisher–Yates simulates a permutation of a huge implicit index range using only a hash map of changed positions.',
'["RandomizedSet: dense array plus value-to-index map","RandomizedCollection: multiset with value-to-set-of-indices map","Reservoir sampling of one item from an unknown-length stream","Reservoir sampling among occurrences matching a query","Fisher–Yates uniform permutation and reset semantics","Sparse Fisher–Yates / virtual swap for sampling without replacement from a huge domain","Rejection sampling to transform one uniform discrete source into another","Uniform continuous sampling in a disk by area-preserving radial transform","Weighted discrete sampling by cumulative weights and binary search","Uniform lattice-point sampling across disjoint weighted regions"]'::jsonb,
'[
 {"trigger":"Insert, delete and sample an element uniformly, all in expected O(1)","breaks_when":"Need sorted iteration or deterministic worst-case O(1)","sub_variant":"Dense array plus hash map; delete by swap-with-last and update the moved index"},
 {"trigger":"The data structure allows duplicate values and must sample occurrences uniformly","breaks_when":"Sampling distinct values uniformly is intended instead of occurrences","sub_variant":"Array plus value-to-index-set; maintain both the moved value and removed value index sets"},
 {"trigger":"Choose a uniformly random element from a stream whose final length is unknown","breaks_when":"The stream can be stored and a second pass is affordable","sub_variant":"Reservoir sampling: replace the current sample at item i with probability 1/i"},
 {"trigger":"Choose a uniformly random matching occurrence without storing all matching positions","breaks_when":"The array is static and there is enough memory for an index list","sub_variant":"Filtered reservoir sampling: the j-th match replaces the sample with probability 1/j"},
 {"trigger":"Return every permutation with equal probability","breaks_when":"Only a random subset is needed","sub_variant":"Fisher–Yates: swap position i with a uniformly chosen position in [i,n)"},
 {"trigger":"Sample without replacement from a huge implicit range such as all matrix cells","breaks_when":"The whole domain is small enough to materialise","sub_variant":"Sparse Fisher–Yates with a hash map of virtual swaps"},
 {"trigger":"Build an unbiased randB from a uniform randA source where A is not divisible by B","breaks_when":"The source itself is biased or has unknown distribution","sub_variant":"Generate a uniform range, reject the excess tail, and map accepted values"},
 {"trigger":"Sample a continuous point uniformly by area inside a disk","breaks_when":"Uniform radius is used directly, which over-samples the centre","sub_variant":"Uniform angle and radius R·sqrt(U), where U is uniform on [0,1]"},
 {"trigger":"Pick an index with probability proportional to a positive weight","breaks_when":"Weights change frequently; a Fenwick tree may be needed for updates","sub_variant":"Prefix sums plus lower_bound on a uniform integer in [1,totalWeight]"},
 {"trigger":"Pick a uniformly random lattice point from a union of disjoint rectangles","breaks_when":"Rectangles overlap or the requested points are continuous","sub_variant":"Weight each rectangle by its integer lattice-point count, prefix-select a rectangle, then sample inside it"}
]'::jsonb,
'["LC 380 — Insert Delete GetRandom O(1)","LC 381 — Insert Delete GetRandom O(1) — Duplicates allowed","LC 382 — Linked List Random Node","LC 398 — Random Pick Index","LC 384 — Shuffle an Array","LC 519 — Random Flip Matrix","LC 470 — Implement Rand10 Using Rand7","LC 478 — Generate Random Point in a Circle","LC 528 — Random Pick with Weight","LC 497 — Random Point in Non-overlapping Rectangles"]'::jsonb,
'[
 "A random-looking algorithm is not necessarily uniform; prove the probability of each outcome.",
 "Modulo reduction is biased unless the source range is divisible by the target range; rejection is the standard correction.",
 "Reservoir sampling must use the number of eligible items seen, not the stream index when filtering.",
 "Fisher–Yates must choose from the remaining suffix; swapping with any arbitrary index does not yield a uniform permutation.",
 "For randomised multisets, the sampling unit is an occurrence, not a distinct key.",
 "In sparse Fisher–Yates, the virtual value at the selected index must be replaced with the last remaining virtual value before the active range shrinks.",
 "For a uniform disk sample, radius is R·sqrt(U), not R·U; area grows quadratically with radius.",
 "Weighted sampling needs positive cumulative weights and a lower-bound search with a clearly defined inclusive/exclusive interval."
]'::jsonb),
(50,
'Sorting is more than a preprocessing line. Staff-level problem solving requires choosing a sorting model from constraints: comparison lower bounds, stability, memory, linked versus random-access storage, key width, and whether the task needs a full order or only a selection boundary. Linear-time integer sorting and constrained in-place partitioning rely on different proofs from ordinary comparison sorting.',
'Comparison sorts cannot beat Ω(n log n) comparisons in the general comparison model. Merge sort obtains O(n log n) worst-case time and stability by merging sorted halves; for linked lists, slow/fast splitting and pointer merging avoid random access, and bottom-up merging can use O(1) auxiliary node storage. QuickSort is typically in-place and expected O(n log n) with randomized pivots but has a quadratic worst case unless guarded; heapsort provides O(n log n) worst-case and O(1) auxiliary array space but is unstable. When keys have bounded structure, counting/radix/bucket methods exploit the key domain. For selection-constrained rearrangement, Quickselect finds a median and three-way partition separates less/equal/greater values; virtual indexing can enforce positional constraints without allocating a second array.',
'["Comparison sorting: merge sort, randomized quicksort, heapsort and stability/space trade-offs","Linked-list merge sort with slow/fast split and pointer-only merge","Pigeonhole bucket decomposition for maximum adjacent sorted gap","Stable LSD radix sorting over fixed-width digit strings","Quickselect median plus Dutch-national-flag partition","Virtual index mapping for wiggle/alternating-position constraints"]'::jsonb,
'[
 {"trigger":"Sort arbitrary values with O(n log n) worst-case time and predictable guarantees","breaks_when":"Stability or O(1) auxiliary space is a hard requirement; choose the matching algorithm","sub_variant":"Merge sort for stability, heapsort for in-place worst-case bounds, or guarded quicksort/introsort"},
 {"trigger":"Sort a singly linked list in O(n log n) without converting it to an array","breaks_when":"The data is random-access and an array sort is simpler","sub_variant":"Linked-list merge sort using slow/fast splitting and pointer merge; bottom-up variant removes recursion stack"},
 {"trigger":"Find maximum adjacent gap in sorted order but sorting is forbidden and values are integers","breaks_when":"The value range is too wide for safe arithmetic or the linear-space constraint is absent","sub_variant":"Pigeonhole principle: distribute into buckets sized from (max−min)/(n−1), then compare successive non-empty bucket extrema"},
 {"trigger":"Repeatedly sort equal-length digit strings by their rightmost t digits, with stable index tie-breaking","breaks_when":"Keys are arbitrary strings or the sort key cannot be processed digit-wise","sub_variant":"Stable LSD radix passes from least-significant digit to more-significant digit; retain original index order for ties"},
 {"trigger":"Rearrange an array into alternating peaks and valleys with many duplicate values","breaks_when":"A strict wiggle ordering is infeasible; validate the input guarantee","sub_variant":"Quickselect median, 3-way partition, then virtual-index mapping to place larger values at odd slots"}
]'::jsonb,
'["LC 912 — Sort an Array","LC 148 — Sort List","LC 164 — Maximum Gap","LC 2343 — Query Kth Smallest Trimmed Number","LC 324 — Wiggle Sort II"]'::jsonb,
'[
 "Do not quote O(n log n) for an unguarded deterministic-pivot QuickSort on adversarial input; its worst case is O(n²).",
 "Merge sort stability depends on choosing the left item on equality during merge.",
 "For linked-list sort, count pointer storage separately from recursion-stack storage; bottom-up merge sort makes the O(1) auxiliary-space claim explicit.",
 "Maximum Gap bucket width and index calculations need wide arithmetic; compare bucket extrema, not every pair inside buckets.",
 "Radix sort must be stable at every digit pass; an unstable pass destroys the ordering established by less-significant digits.",
 "Wiggle Sort II must handle duplicates; sorting then interleaving halves is not a general O(n) in-place solution."
]'::jsonb)
on conflict (topic_id) do nothing;

-- Extend existing pattern homes with verified questions from the dump.
update public.topic_content
set sub_variants=sub_variants || '["Pairwise candidate elimination with a final oracle-verification pass"]'::jsonb,
 pattern_triggers=pattern_triggers || '[{"trigger":"An unknown item is the unique candidate satisfying a one-way relation against every other item, and relation queries are available","breaks_when":"The relation is noisy or non-transitive, or the final candidate is not verified against every item","sub_variant":"Eliminate one candidate per comparison, then verify both required directions against all others"}]'::jsonb,
 core_idea=core_idea || E'\n\nCandidate elimination with an oracle: compare the current candidate c with each other item i. If knows(c,i) is true, c cannot be the celebrity, so replace it with i; otherwise i cannot be the celebrity. One pass leaves at most one candidate. A second pass is mandatory to verify that the candidate knows nobody and everybody knows the candidate. This gives O(n) oracle calls and makes the elimination proof explicit.'
where topic_id=1 and not (sub_variants @> '["Pairwise candidate elimination with a final oracle-verification pass"]'::jsonb);

update public.topic_content
set sub_variants=sub_variants || '["Value-window membership with ordered predecessor/successor or bucket indexing"]'::jsonb,
 pattern_triggers=pattern_triggers || '[{"trigger":"Find two values within a sliding index distance k whose absolute value difference is at most t","breaks_when":"The window is not bounded by index distance, or arithmetic cannot safely represent value differences","sub_variant":"Maintain the last k values in an ordered set (predecessor/successor) or buckets of width t+1; use floor division for negatives"}]'::jsonb,
 core_idea=core_idea || E'\n\nValue-window queries are not ordinary frequency windows: the state is the set of values in the last k indices, and validity is a nearest-value query. An ordered set checks lower_bound and predecessor in O(log k); a bucket method with width t+1 gives expected O(1) lookup by checking the same and adjacent buckets. Remove the expired index after testing the current value, and use mathematical floor division for negative values.'
where topic_id=4 and not (sub_variants @> '["Value-window membership with ordered predecessor/successor or bucket indexing"]'::jsonb);

update public.topic_content
set sub_variants=sub_variants || '["Minimax feedback search: choose guesses that minimise the largest surviving candidate bucket"]'::jsonb,
 pattern_triggers=pattern_triggers || '[{"trigger":"A secret item is selected from a finite candidate set and each query returns a feedback class; reach the secret within a small query budget","breaks_when":"Feedback does not partition candidates deterministically or the worst-case bound cannot be met by the chosen strategy","sub_variant":"Minimax partitioning: choose the guess whose largest feedback bucket is smallest; filter candidates after each response"}]'::jsonb,
 core_idea=core_idea || E'\n\nMinimax search with feedback: A guess partitions the remaining secrets by the feedback score it would produce. A strong guess minimises the size of the largest resulting bucket, rather than simply choosing an arbitrary candidate. After observing feedback, discard every candidate in an inconsistent bucket. This is an adversarial decision-tree problem; distinguish a minimax worst-case objective from average-case entropy heuristics.'
where topic_id=37 and not (sub_variants @> '["Minimax feedback search: choose guesses that minimise the largest surviving candidate bucket"]'::jsonb);

update public.topic_content
set sub_variants=sub_variants || '["Combinatorial probability by colour-allocation counts and binomial weights","Symmetry and first-collision arguments in random seating"]'::jsonb,
 pattern_triggers=pattern_triggers || '[
 {"trigger":"Uniformly split repeated categories into two equal-capacity boxes and compare category counts","breaks_when":"Physical outcomes are not equally likely under the assumed allocation model","sub_variant":"Enumerate per-category allocations and weight each by its binomial coefficient"},
 {"trigger":"A sequential random seating process appears to have many states but only one displaced passenger matters","breaks_when":"The process has more than one arbitrary passenger or the seat-choice rule changes","sub_variant":"Symmetry: track the first passenger's displaced-seat chain; the final ambiguity is between the first and last seats"}
]'::jsonb,
 core_idea=core_idea || E'\n\nCombinatorial probability: when identical-colour objects are split into distinguishable boxes, enumerate how many of each colour enter the first box. A split x_i contributes weight C(balls[i],x_i); multiply across colours, keep the capacity and distinct-colour-count difference as state, and divide favourable weighted allocations by C(total,half). This is different from a Markov transition DP: it is a weighted count over combinatorial outcomes.'
where topic_id=40 and not (sub_variants @> '["Combinatorial probability by colour-allocation counts and binomial weights"]'::jsonb);

update public.topic_content
set sub_variants=sub_variants || '["Weighted dictionary segmentation using rolling-hash length buckets and prefix-minimum DP"]'::jsonb,
 pattern_triggers=pattern_triggers || '[{"trigger":"Construct a target by concatenating dictionary strings with different costs, with a large dictionary and total dictionary length bounded","breaks_when":"All dictionary lengths are small/few enough for direct trie scanning, or hashes are used without collision protection","sub_variant":"dp[end] = min(dp[start]+cost); group words by length, keep minimum cost per hash, and probe target suffix hashes"}]'::jsonb,
 core_idea=core_idea || E'\n\nWeighted dictionary segmentation: define dp[i] as the minimum cost to build target[0..i). A word of length L ending at i gives dp[i] = min(dp[i], dp[i−L]+minCost(word)). Group dictionary words by length and retain the cheapest word for each content; rolling hashes let each target suffix be checked against the relevant length buckets. The total-length bound limits the number of distinct word lengths; use double hashing or verify hash matches to control collisions. Aho–Corasick is an alternative multi-pattern matching front end.'
where topic_id=46 and not (sub_variants @> '["Weighted dictionary segmentation using rolling-hash length buckets and prefix-minimum DP"]'::jsonb);

update public.topic_content
set sub_variants=sub_variants || '["Rectangle exact-cover verification by total area plus corner parity","Union-area quantile search by sweep slabs and covered-length segment tree","Continuous geometric median via iterative convex optimisation (reference)"]'::jsonb,
 pattern_triggers=pattern_triggers || '[
 {"trigger":"Many axis-aligned rectangles must tile one bounding rectangle exactly, with no gaps or overlaps","breaks_when":"The union need not be a single rectangle or coordinates are not axis-aligned","sub_variant":"Bounding-box area equality plus parity cancellation of internal corners"},
 {"trigger":"Find the horizontal line that bisects the union area of overlapping rectangles or squares","breaks_when":"Overlaps should be counted with multiplicity rather than union area","sub_variant":"Sweep y-events; maintain covered x-length with a segment tree; accumulate slab areas and interpolate inside the target slab"},
 {"trigger":"Choose a point in the plane minimising the sum of Euclidean distances to given points","breaks_when":"Objective is squared distance (centroid is then optimal) or a closed-form metric median is required","sub_variant":"Geometric median via Weiszfeld/gradient-style iterative convex optimisation"}
]'::jsonb,
 core_idea=core_idea || E'\n\nRectangle coverage and area quantiles: Exact tiling can be tested by combining the total area with the parity of rectangle corners: internal corners cancel, leaving only the four corners of the bounding rectangle. For overlapping shapes counted once, use a sweep line and a segment tree over compressed x-intervals to maintain covered length. Each y-slab contributes coveredLength×height; locate the half-area threshold within the slab and interpolate the y coordinate. Do not sum individual rectangle areas when overlaps are excluded.'
where topic_id=48 and not (sub_variants @> '["Rectangle exact-cover verification by total area plus corner parity"]'::jsonb);

-- New required questions in existing topic homes.
insert into public.problems
(topic_id,order_num,layer,lc_number,lc_url,title,difficulty,is_premium,sub_variant,key_insight,is_required,curriculum_role,curriculum_path,curriculum_path_order,path_problem_order)
values
(1,59,'Variants','277','https://leetcode.com/problems/find-the-celebrity/','Find the Celebrity','Med',false,'Candidate elimination with oracle verification','Maintain one candidate c. For each i≠c, if knows(c,i), c cannot be the celebrity and i becomes the only surviving candidate; otherwise i cannot be the celebrity. After one pass, verify knows(c,j)=false and knows(j,c)=true for every j≠c. The second pass is essential: elimination proves at most one candidate survives, not that a celebrity exists. O(n) oracle calls.',true,'core_pattern','Pairwise candidate elimination and oracle verification',5,1),
(4,56,'Hard','220','https://leetcode.com/problems/contains-duplicate-iii/','Contains Duplicate III','Hard',false,'Sliding value window with ordered set or bucket partition','Maintain only the previous indexDiff elements. With a TreeSet, inspect the smallest value ≥ x−valueDiff and check it ≤ x+valueDiff. With buckets of width valueDiff+1, a value in the same bucket is immediately valid; only adjacent buckets need exact checks. Remove the expired value after the current query. Use long arithmetic and floorDiv for negative values; valueDiff=0 is a useful boundary case.',true,'combination','Sorted-value windows',6,2),
(37,29,'Hard','843','https://leetcode.com/problems/guess-the-word/','Guess the Word','Hard',false,'Minimax feedback partitioning','Each guess partitions the remaining candidate words by the number of exact-position matches returned by the oracle. For every possible guess, count candidates in feedback buckets 0..6; choose a guess minimising the largest bucket (worst-case survivor count), then filter candidates to the observed bucket. The constraints make pairwise scoring feasible. Explain why random/arbitrary candidate guesses can waste the bounded query budget and distinguish worst-case minimax from average-case entropy.',true,'combination','Minimax, bitmask and cyclic game states',3,8),
(40,17,'Hard','1467','https://leetcode.com/problems/probability-of-a-two-boxes-having-the-same-number-of-distinct-balls/','Probability of a Two Boxes Having the Same Number of Distinct Balls','Hard',false,'Combinatorial probability with weighted colour allocations','For each colour with c balls, choose x for box A and c−x for box B; this allocation represents C(c,x) physical choices. Multiply these binomial weights across colours, and memoize by colour index, remaining capacity in A and the difference in distinct-colour counts. Sum weights when both boxes have n balls and the difference is zero; divide by C(2n,n). This is weighted combinatorial counting, not a Markov-chain transition.',true,'combination','Combinatorial probability and weighted allocations',4,1),
(46,8,'Hard','3213','https://leetcode.com/problems/construct-string-with-minimum-cost/','Construct String with Minimum Cost','Hard',false,'Weighted word-break DP accelerated by hashing or multi-pattern matching','Let dp[i] be the minimum cost to build target[0..i). A dictionary word of length L ending at i relaxes dp[i] from dp[i−L]. Group words by length and keep the minimum cost for identical words/hashes; hash each target suffix for every distinct length, or use an Aho–Corasick matching front end. The total dictionary length bound limits distinct lengths; use collision-resistant double hashing or verify hits. Return −1 if the final prefix is unreachable.',true,'combination','Weighted dictionary matching and segmentation',5,1),
(48,11,'Hard','391','https://leetcode.com/problems/perfect-rectangle/','Perfect Rectangle','Hard',false,'Exact rectangle cover from area and corner parity','Compute the bounding box and sum of all small-rectangle areas. Toggle each rectangle corner in a set (insert if absent, remove if present). A perfect tiling requires total area equal to the bounding-box area and the remaining odd-parity corners to be exactly the four bounding corners. Explain why area alone misses compensating gaps/overlaps and why the parity invariant captures internal boundary cancellation.',true,'combination','Rectangle coverage and area quantiles',4,1),
(48,12,'Hard','3454','https://leetcode.com/problems/separate-squares-ii/','Separate Squares II','Hard',false,'Sweep-line union area and horizontal area quantile','Overlaps count once, so individual square areas cannot be summed. Sweep bottom/top y-events; coordinate-compress x endpoints and maintain covered x-length in a segment tree. Each slab contributes coveredLength×deltaY. Find the first slab where cumulative union area reaches half the total and interpolate within that slab; handle equal-y events and exact-threshold boundaries. O(n log n).',true,'combination','Rectangle coverage and area quantiles',4,2);

-- Optional references: useful reasoning extensions, not core mastery gates.
insert into public.problems
(topic_id,order_num,layer,lc_number,lc_url,title,difficulty,is_premium,sub_variant,key_insight,is_required,curriculum_role,curriculum_path,curriculum_path_order,path_problem_order)
values
(40,18,'Variants','1227','https://leetcode.com/problems/airplane-seat-assignment-probability/','Airplane Seat Assignment Probability','Med',false,'Symmetry and first-displaced-seat argument','For n≥2, the first passenger either sits in their own seat, leaving the process unchanged, or takes a later seat. Follow the chain of displaced passengers: the process ends when the first passenger''s seat or the last passenger''s seat is selected. By symmetry these two terminal outcomes are equally likely, so the last passenger sits correctly with probability 1/2. This is a symmetry argument, not a probability DP.',false,'optional_reference',null,null,null),
(48,13,'Variants','1515','https://leetcode.com/problems/best-position-for-a-service-centre/','Best Position for a Service Centre','Hard',false,'Geometric median and iterative convex optimisation','Minimise the sum of Euclidean distances from a point to all customers: this is the geometric-median objective, not the centroid (which minimises squared distances). The objective is convex but has no simple closed form in general. Use a carefully convergent iterative method (for example, Weiszfeld with handling when the iterate coincides with a data point) and validate the stopping tolerance against the 1e−5 requirement.',false,'optional_reference',null,null,null);

-- New primary home: randomized algorithms and sampling.
insert into public.problems
(topic_id,order_num,layer,lc_number,lc_url,title,difficulty,is_premium,sub_variant,key_insight,is_required,curriculum_role,curriculum_path,curriculum_path_order,path_problem_order)
values
(49,1,'Foundation','380','https://leetcode.com/problems/insert-delete-getrandom-o1/','Insert Delete GetRandom O(1)','Med',false,'Dense array plus value-to-index map','Store values in a dense array and map each value to its index. Insert appends; getRandom chooses a uniform array index. Delete swaps the target with the last array element, updates the moved value''s index, then removes the tail. The array makes uniform sampling and O(1) deletion possible; the map makes lookup O(1) expected.',true,'core_pattern','Randomized O(1) data structures',1,1),
(49,2,'Variants','381','https://leetcode.com/problems/insert-delete-getrandom-o1-duplicates-allowed/','Insert Delete GetRandom O(1) — Duplicates allowed','Hard',false,'Multiset array plus value-to-index-set map','Keep every occurrence in a dense array and map each value to the set of indices where it occurs. Insert records the new index. Delete chooses one stored index, swaps in the final array occurrence, updates the moved value''s index set, and removes the old index. getRandom samples an array position, so occurrences—not distinct values—are uniform. Handle the case where the removed and moved values are equal without corrupting the index set.',true,'variant','Randomized O(1) data structures',1,2),
(49,3,'Foundation','382','https://leetcode.com/problems/linked-list-random-node/','Linked List Random Node','Med',false,'Reservoir sampling with k=1','Traverse the linked list once. At the i-th node (1-indexed), replace the current answer with that node with probability 1/i. A node chosen at position j survives all later steps with probability Π(i=j+1..n)(1−1/i)=j/n, so every node has final probability 1/n. O(n) time and O(1) space without knowing the list length.',true,'core_pattern','Reservoir sampling from streams',2,1),
(49,4,'Variants','398','https://leetcode.com/problems/random-pick-index/','Random Pick Index','Med',false,'Filtered reservoir sampling','Scan the array and count only occurrences equal to target. For the j-th matching occurrence, replace the answer with probability 1/j. Every matching index ends with probability 1/m where m is the number of matches. This avoids storing all matching positions and is the filtered-stream generalisation of reservoir sampling.',true,'variant','Reservoir sampling from streams',2,2),
(49,5,'Foundation','384','https://leetcode.com/problems/shuffle-an-array/','Shuffle an Array','Med',false,'Fisher–Yates uniform permutation','For i from n−1 down to 1, choose j uniformly from [0,i] and swap positions i and j. At step i, every remaining element is equally likely to occupy i; multiplying conditional probabilities gives every permutation probability 1/n!. Always shuffle from the original array for reset semantics.',true,'core_pattern','Uniform permutations and sampling without replacement',3,1),
(49,6,'Hard','519','https://leetcode.com/problems/random-flip-matrix/','Random Flip Matrix','Hard',false,'Sparse Fisher–Yates over an implicit matrix index range','Flatten the m×n cells to [0,mn). Maintain remaining=N and a hash map representing only virtual swaps. Draw r uniformly from [0,remaining); output map[r] if present else r. Replace map[r] with the virtual value at remaining−1, erase the old tail mapping, then decrement remaining. This samples without replacement in O(1) expected time and O(number of flips) space, avoiding a matrix-sized visited array and long rejection loops.',true,'combination','Uniform permutations and sampling without replacement',3,2),
(49,7,'Variants','470','https://leetcode.com/problems/implement-rand10-using-rand7/','Implement Rand10 Using Rand7','Med',false,'Rejection sampling to remove modulo bias','Combine two independent uniform rand7 calls to create a uniform integer in [0,48]. Accept only a range whose size is divisible by 10 (for example 0..39), then map modulo 10; reject the excess tail and retry. Explain why direct rand7()%10 is biased and derive the expected number of source calls. Consider recycling rejected outcomes as an optimisation.',true,'core_pattern','Unbiased generation and continuous transforms',4,1),
(49,8,'Variants','478','https://leetcode.com/problems/generate-random-point-in-a-circle/','Generate Random Point in a Circle','Med',false,'Inverse-transform sampling for a uniform disk','Choose theta uniformly from [0,2π) and U uniformly from [0,1); set r=R·sqrt(U). The square root is required because disk area up to radius r is proportional to r²; choosing r uniformly overweights the centre. Translate by the circle centre and prove uniformity by comparing annulus area to total area.',true,'variant','Unbiased generation and continuous transforms',4,2),
(49,9,'Foundation','528','https://leetcode.com/problems/random-pick-with-weight/','Random Pick with Weight','Med',false,'Prefix-sum weighted discrete sampling','Build cumulative weights C[i]. Draw an integer uniformly from [1,totalWeight] and return the first index with C[i]≥draw using lower_bound. Index i receives exactly weight[i] equally likely draws, so its probability is weight[i]/totalWeight. Use long for the cumulative total.',true,'core_pattern','Weighted discrete sampling over large domains',5,1),
(49,10,'Hard','497','https://leetcode.com/problems/random-point-in-non-overlapping-rectangles/','Random Point in Non-overlapping Rectangles','Med',false,'Weighted rectangle selection by integer lattice-point count','For each rectangle, count its integer lattice points as (x2−x1+1)(y2−y1+1). Build prefix sums of these counts, draw one integer in [1,total], and binary-search the selected rectangle. Convert the residual offset into a uniform row/column offset inside that rectangle. Weight by point count, not by rectangle count; this makes every lattice point equiprobable.',true,'combination','Weighted discrete sampling over large domains',5,2);

-- New primary home: sorting and order-statistic algorithms.
insert into public.problems
(topic_id,order_num,layer,lc_number,lc_url,title,difficulty,is_premium,sub_variant,key_insight,is_required,curriculum_role,curriculum_path,curriculum_path_order,path_problem_order)
values
(50,1,'Foundation','912','https://leetcode.com/problems/sort-an-array/','Sort an Array','Med',false,'Comparison sorting guarantees and trade-offs','Implement a comparison sort rather than relying only on a library call. Derive merge sort O(n log n) worst-case and stable behaviour; compare randomized quicksort (expected O(n log n), O(n²) worst case), heapsort (O(n log n) worst-case, O(1) auxiliary array space, unstable), and an introspective fallback. State which constraints determine the choice.',true,'core_pattern','Comparison sorting and linked-list merge sort',1,1),
(50,2,'Variants','148','https://leetcode.com/problems/sort-list/','Sort List','Med',false,'Linked-list merge sort with pointer-only merge','Split the linked list with slow/fast pointers, recursively sort each half and merge by relinking nodes—no random access or element copying. Top-down merge sort uses O(log n) recursion stack; bottom-up width-doubling merge sort can achieve O(1) auxiliary node storage while retaining O(n log n) time. Explain stable tie handling and termination for odd/even lengths.',true,'variant','Comparison sorting and linked-list merge sort',1,2),
(50,3,'Hard','164','https://leetcode.com/problems/maximum-gap/','Maximum Gap','Med',false,'Pigeonhole buckets for linear-time maximum adjacent gap','Let range=max−min. The maximum adjacent sorted gap is at least ceil(range/(n−1)). Choose bucket width at least that bound; at least one bucket is empty, so the maximum gap must occur between consecutive non-empty buckets. Store only each bucket minimum and maximum, then scan them in order. Use wide arithmetic and handle n<2 or all-equal input.',true,'core_pattern','Linear-time integer sorting and radix passes',2,1),
(50,4,'Variants','2343','https://leetcode.com/problems/query-kth-smallest-trimmed-number/','Query Kth Smallest Trimmed Number','Med',false,'Stable LSD radix passes for repeated suffix-order queries','All strings have equal length and ties are broken by original index. Start with indices in original order. For trim length t=1..maxTrim, stably counting-sort the current index order by the next digit moving left; stability preserves the less-significant suffix order and original-index tie order. Answer queries grouped by trim using the resulting order. This avoids sorting every query independently.',true,'combination','Linear-time integer sorting and radix passes',2,2),
(50,5,'Hard','324','https://leetcode.com/problems/wiggle-sort-ii/','Wiggle Sort II','Med',false,'Quickselect median, Dutch-national-flag partition and virtual indexing','Find the median with Quickselect, then perform a three-way partition around it using virtual index mapping (1+2·i) mod (n|1), which visits odd slots before even slots. Place values greater than the median at peak positions and smaller values at valley positions; equal values occupy the middle. The guarantee that a valid answer exists is essential. Explain the virtual-index permutation and duplicate handling.',true,'combination','Selection and in-place constrained partitioning',3,1)
on conflict (topic_id,order_num) do nothing;

-- Ensure the two new topic content records exist before updating their summaries.
update public.topic_content set core_idea=core_idea where topic_id in (49,50);

-- Existing topic summaries are kept in sync with the new rows.
update public.topics set summary_meta='59 problems · sorted pair, fast/slow, in-place transforms, boundary scans and candidate elimination' where id=1;
update public.topics set summary_meta='56 problems · variable/fixed windows, exact-K, deque, complement and value-neighbour windows' where id=4;
update public.topics set summary_meta='29 problems · 23 required · impartial games, score DP, Grundy, minimax and feedback search' where id=37;
update public.topics set summary_meta='18 problems · 12 required · probability DP, expectation, Markov chains and combinatorial allocation' where id=40;
update public.topics set summary_meta='8 problems · rolling hash, suffix arrays, LCP, suffix automata, Manacher and weighted segmentation' where id=46;
update public.topics set summary_meta='13 problems · 12 required · predicates, polygons, hulls, closest pair, sweeps and union-area quantiles' where id=48;

-- Extend the probability home with the new combinatorial allocation and symmetry coverage.
update public.topic_content set
 coverage_problems=coverage_problems || '["LC 1467 — Probability of a Two Boxes Having the Same Number of Distinct Balls","LC 1227 — Airplane Seat Assignment Probability"]'::jsonb
where topic_id=40 and not (coverage_problems @> '["LC 1467 — Probability of a Two Boxes Having the Same Number of Distinct Balls"]'::jsonb);

-- Reconcile the sequence after explicit topic IDs 49 and 50.
do $$
declare seq_name text;
begin
  seq_name := pg_get_serial_sequence('public.topics','id');
  if seq_name is not null then
    perform setval(seq_name, greatest((select coalesce(max(id),1) from public.topics), 1), true);
  end if;
end $$;

commit;
